  }, fields || {});
  const parts = Object.keys(f).filter(k => f[k] !== null && f[k] !== undefined)
    .map(k => `${k}=${f[k]}`);
  const line = `[${wf}][exec=${ctx.execution_id || '-'}]` +
               `[${f.route_key || '-'}] ` + parts.join(' ') +
               (ctx.phone ? ` phone=...${lmMaskPhone(ctx.phone)}` : '');
